// Writes Runtime/World/Fish/EagleRayData.cs and StingrayData.cs from src/world/fish/EagleRayData.js and StingrayData.js (the baked rays, themselves
// generated by tools/creatures/bake-eagle-ray.mjs and bake-stingray-family.mjs from assets/eagle-ray.glb and assets/stingray-family.glb): the four
// levels of detail as base64 strings and the numbers CreatureGeometry.bakedRayGeometry needs.    node unity/tools/dump-eagle-ray.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve( path.dirname( fileURLToPath( import.meta.url ) ), '../..' );
const chunk = ( s ) => s.match( /.{1,120}/g ).map( ( l ) => `\t\t\t"${ l }"` ).join( ' +\n' );
for ( const [ cls, js, bake, glb, what ] of [
	[ 'EagleRayData', 'EagleRayData', 'bake-eagle-ray', 'eagle-ray', 'spotted eagle ray' ],
	[ 'StingrayData', 'StingrayData', 'bake-stingray-family', 'stingray-family', 'southern stingray' ] ] ) {

	const mod = await import( root + `/src/world/fish/${ js }.js` );
	const D = mod.EAGLE_RAY || mod.STINGRAY;
	const cs = `// GENERATED by unity/tools/dump-eagle-ray.mjs from src/world/fish/${ js }.js (itself baked by tools/creatures/${ bake }.mjs from
// assets/${ glb }.glb): do not edit. The ${ what } in the fish frame, ${ D.lods.length } levels of detail as base64: uint32 vertex count, uint32
// triangle count, then per vertex int16 x y z (/ scale), uint8 part, int8 w (+1 back, -1 belly), then uint16 indices.
namespace Tidewater.World.Fish
{
	public static class ${ cls }
	{
		public const double scale = ${ D.scale };
		public const double whipRoot = ${ D.meta.whipU.root }, whipK = ${ D.meta.whipU.k };
		public static readonly double[][] eyes = { ${ D.meta.eyes.map( ( e ) => 'new[] { ' + e.join( ', ' ) + ' }' ).join( ', ' ) } };
		public static readonly string[] lods =
		{
${ D.lods.map( ( l ) => chunk( l ) ).join( ',\n' ) }
		};
	}
}
`;
	const dest = path.join( root, `unity/Assets/Tidewater/Runtime/World/Fish/${ cls }.cs` );
	fs.writeFileSync( dest, cs );
	console.log( 'wrote', dest, cs.length, 'bytes' );

}
